// useEvaluationForm.ts — all EvaluationForm logic
import { useState, useEffect, useCallback } from "react";
import { EvaluationFormData } from "../services/IEvaluationService";
import { QuestionItem } from "../services/QuestionnaireApi/IQuestionnaireApi";
import { evaluationService } from "../services/EvaluationApiService";


export const SCORECARD_FIELDS = [
  { key: "Qualifications",  label: "QUALIFICATIONS",  icon: "📄" },
  { key: "Experience",      label: "EXPERIENCE",       icon: "📈" },
  { key: "Knowledge",       label: "KNOWLEDGE",        icon: "🧩" },
  { key: "EnergyLevel",     label: "ENERGY LEVEL",     icon: "⚡" },
  { key: "JobRequirements", label: "JOB REQUIREMENTS", icon: "⏱" },
  { key: "CultureFit",      label: "CULTURE FIT",      icon: "👥" },
  { key: "ExpatLocal",      label: "EXPAT/LOCAL",      icon: "🌐" },
  { key: "OtherCriteria",   label: "OTHER CRITERIA",   icon: "📋" },
] as const;
export const SCORE_RATING = [{ key: 1, text: "Not Acceptable" }, { key: 2, text: "Acceptable" }, { key: 3, text: "Excellent" }] as const;
export type ScorecardKey   = typeof SCORECARD_FIELDS[number]["key"];
export type ScorecardState = Record<ScorecardKey, number | null>;

const blank = (): ScorecardState =>
  Object.fromEntries(SCORECARD_FIELDS.map(f => [f.key, null])) as ScorecardState;

export function useEvaluationForm(
  candidateId: number, recruitmentId: number, email: string, roleIDs: number[], onSuccess: () => void
) {
  const [loading,    setLoading]    = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [formData,   setFormData]   = useState<EvaluationFormData | null>(null);
  const [alertMsg,   setAlertMsg]   = useState("");
  const [alertType,  setAlertType]  = useState<"success" | "error" | "">("");

  const [questionnaire,   setQuestionnaire]   = useState<QuestionItem[]>([]);
  const [ratingErrors,    setRatingErrors]     = useState<Record<number, boolean>>({});
  const [scorecard,       setScorecard]        = useState<ScorecardState>(blank());
  const [scorecardErrors, setScorecardErrors]  = useState<Record<string, boolean>>({});
  const [recommendation,  setRecommendation]   = useState<"consider" | "doNotConsider" | null>(null);
  const [recError,        setRecError]         = useState(false);
  const [overallFeedback, setOverallFeedback]  = useState("");
  const [feedbackError,   setFeedbackError]    = useState(false);
  const [acknowledged,    setAcknowledged]     = useState(false);
  const [ackError,        setAckError]         = useState(false);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      const result = await evaluationService.getEvaluationFormData(candidateId, recruitmentId, email);
      if (cancelled) return;
      if (result.success) {
        setFormData(result);
        setQuestionnaire((result.questions ?? []).map((q: any, i: number) => ({ id: q.id ?? i, question: q.question ?? q.Question ?? "", answer: q.answer ?? q.Answer ?? "", rating: null })));
      }
      setLoading(false);
    })();
    return () => { cancelled = true; };
  }, [candidateId, recruitmentId, email]);

  const handleRatingChange = useCallback((id: number, value: { key: number } | null) => {
    setQuestionnaire(prev => prev.map(q => q.id === id ? { ...q, rating: value?.key ?? null } : q));
    if (value) setRatingErrors(prev => ({ ...prev, [id]: false }));
  }, []);

  const handleScorecardChange = useCallback((key: ScorecardKey, value: number) => {
    setScorecard(prev => ({ ...prev, [key]: value }));
    setScorecardErrors(prev => ({ ...prev, [key]: false }));
  }, []);

  const handleRecommendation = useCallback((val: "consider" | "doNotConsider") => { setRecommendation(val); setRecError(false); }, []);
  const handleFeedback       = useCallback((val: string)  => { setOverallFeedback(val);  if (val.trim())    setFeedbackError(false); }, []);
  const handleAcknowledge    = useCallback((v: boolean)   => { setAcknowledged(v);       if (v)             setAckError(false); },    []);
  const hideAlert            = useCallback(()             => { setAlertMsg(""); setAlertType(""); }, []);

  const handleSubmit = async () => {
    let valid = true;
    const nRE: Record<number, boolean> = {};
    questionnaire.forEach(q => { if (q.rating === null) { nRE[q.id] = true; valid = false; } });
    setRatingErrors(nRE);
    const nSE: Record<string, boolean> = {};
    SCORECARD_FIELDS.forEach(f => { if (scorecard[f.key] === null) { nSE[f.key] = true; valid = false; } });
    setScorecardErrors(nSE);
    if (!recommendation)        { setRecError(true);     valid = false; }
    if (!overallFeedback.trim()) { setFeedbackError(true); valid = false; }
    if (!acknowledged)           { setAckError(true);     valid = false; }
    if (!valid) { setAlertMsg("Please complete all required fields."); setAlertType("error"); return; }
    if (!formData?.currentUserPanelId) { setAlertMsg("Could not identify your panel entry."); setAlertType("error"); return; }

    setSubmitting(true);
    const payload = { RecruitmentIDId: recruitmentId, Qualifications: scorecard.Qualifications, Experience: scorecard.Experience, Knowledge: scorecard.Knowledge, EnergyLevel: scorecard.EnergyLevel, JobRequirements: scorecard.JobRequirements, CultureFit: scorecard.CultureFit, ExpatLocal: scorecard.ExpatLocal, OtherCriteria: scorecard.OtherCriteria, Recommendation: recommendation === "consider" ? "Consider for Employment" : "Do Not Consider", OverallFeedback: overallFeedback, QuestionScores: JSON.stringify(questionnaire.map(q => ({ id: q.id, rating: q.rating }))) };
    const roleIdToSave = roleIDs.includes(4) ? 4 : (roleIDs[0] ?? 0);
    const result = await evaluationService.submitScorecard(payload, formData.currentUserPanelId, roleIdToSave, formData.currentUserGuid ?? "");
    setSubmitting(false);
    if (result.success) { setAlertMsg(result.message); setAlertType("success"); setTimeout(onSuccess, 1600); }
    else                { setAlertMsg(result.message); setAlertType("error"); }
  };

  return { loading, submitting, formData, questionnaire, ratingErrors, handleRatingChange, scorecard, scorecardErrors, handleScorecardChange, recommendation, recError, handleRecommendation, overallFeedback, feedbackError, handleFeedback, acknowledged, ackError, handleAcknowledge, alertMsg, alertType, hideAlert, handleSubmit, SCORECARD_FIELDS, SCORE_RATING };
}